B.Gt=new A.dt("SHOW ME THE BOARD",B.KP,B.Kb,null,"mira_showed_board",null,null,null,null,null)
B.Jg=A.a(s(["There was no whisper-vote. Each of us who stepped in did so alone. Remember the choice, or you remember a lie."]),t.s)
