B.Gz=new A.dt("ASK FOR THE ARCHIVE SEAL",B.LL,B.Mb,"archive_seal",null,"archivist_seal",null,null,null,"archive_seal")
B.Mr=A.a(s(["I wrote that line so no one else would have to. It did not save them.","Go. If your Gaia is different, prove it. If she is not \u2014 I will finish what I started."]),t.s)
B.Kw=A.a(s(["audio/voices/voss_confront_1.mp3","audio/voices/voss_confront_2.mp3"]),t.s)
B.GA=new A.dt("CONFRONT HIM WITH THE ORDERS",B.Mr,B.Kw,null,"confronted_voss_orders",null,null,null,null,null)
B.KN=A.a(s(["Then walk with open eyes. The Archivist holds a seal you may need."]),t.s)
