B.GC=new A.dt("PROMISE TO CARRY THE NAMES",B.Kd,B.Ks,null,"asha_archive_ack",null,null,null,null,null)
B.K2=A.a(s(["Browse the stall \u2014 salvage and colony trinkets. Pay with glimmer from jobs and finds."]),t.s)
